CREATE OR REPLACE FUNCTION public.record_coach_agent_lesson_from_send() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_proposed jsonb; v_accepted_payload jsonb; v_accepted jsonb; BEGIN IF NEW.status NOT IN ('sent', 'kept') THEN RETURN NEW; END IF; IF OLD.status IS NOT DISTINCT FROM NEW.status THEN RETURN NEW; END IF; IF OLD.status IS DISTINCT FROM 'pending' THEN RETURN NEW; END IF; v_proposed := public.coach_agent_payload_fingerprint(COALESCE(OLD.payload->'agent_proposed', OLD.payload)); v_accepted_payload := NEW.payload; IF NEW.applied_values ? 'calories' THEN v_accepted_payload := v_accepted_payload || jsonb_build_object('calories', NEW.applied_values->'calories', 'protein', NEW.applied_values->'protein', 'carbs', NEW.applied_values->'carbs', 'fat', NEW.applied_values->'fat'); END IF; v_accepted := public.coach_agent_payload_fingerprint(v_accepted_payload); IF v_proposed = '{}'::jsonb AND v_accepted = '{}'::jsonb THEN RETURN NEW; END IF; IF v_proposed IS NOT DISTINCT FROM v_accepted THEN RETURN NEW; END IF; INSERT INTO public.coach_agent_lessons (coach_id, kind, proposed, accepted, intervention_id) VALUES (NEW.coach_id, NEW.kind, v_proposed, v_accepted, NEW.id); RETURN NEW; EXCEPTION WHEN OTHERS THEN RAISE WARNING 'record_coach_agent_lesson_from_send: %', SQLERRM; RETURN NEW; END; $$; ALTER TABLE public.coach_agent_lessons ADD COLUMN IF NOT EXISTS disabled boolean NOT NULL DEFAULT false; DROP POLICY IF EXISTS "Coaches update own agent lessons" ON public.coach_agent_lessons; CREATE POLICY "Coaches update own agent lessons" ON public.coach_agent_lessons FOR UPDATE TO authenticated USING (coach_id = (select auth.uid())) WITH CHECK (coach_id = (select auth.uid())); DROP POLICY IF EXISTS "Coaches delete own agent lessons" ON public.coach_agent_lessons; CREATE POLICY "Coaches delete own agent lessons" ON public.coach_agent_lessons FOR DELETE TO authenticated USING (coach_id = (select auth.uid())); GRANT UPDATE, DELETE ON TABLE public.coach_agent_lessons TO authenticated; ALTER TABLE public.coach_messages ADD COLUMN IF NOT EXISTS client_msg_id text; CREATE UNIQUE INDEX IF NOT EXISTS coach_messages_sender_client_msg_uidx ON public.coach_messages (sender_id, client_msg_id) WHERE client_msg_id IS NOT NULL;
